<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
require __DIR__.'/saas_feature_helpers.php';
saas_require_login();$tourId=saas_require_tour();saas_require_permission('settings.manage');$orgId=saas_current_organization_id();$db=saas_db();$error='';$ok='';$catalog=saas_feature_catalog();
$q=$db->prepare('SELECT * FROM tour_features WHERE tour_id=? ORDER BY id');$q->execute([$tourId]);$existing=[];foreach($q->fetchAll() as $r)$existing[$r['feature_key']]=$r;
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$key=(string)($_POST['feature_key']??'');if(!isset($catalog[$key]))throw new RuntimeException('Invalid feature.');$enabled=isset($_POST['enabled'])?1:0;$config=['label'=>trim((string)($_POST['label']??$catalog[$key]['label'])),'description'=>trim((string)($_POST['description']??$catalog[$key]['description']))];$db->beginTransaction();$q=$db->prepare('INSERT INTO tour_features(tour_id,feature_key,enabled,config_json) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),config_json=VALUES(config_json)');$q->execute([$tourId,$key,$enabled,json_encode($config,JSON_UNESCAPED_UNICODE)]);$db->commit();saas_audit('tour_feature.updated','tour_feature',null,json_encode(['feature'=>$key,'enabled'=>$enabled],JSON_UNESCAPED_UNICODE));$ok='Feature settings saved.';$q=$db->prepare('SELECT * FROM tour_features WHERE tour_id=? ORDER BY id');$q->execute([$tourId]);$existing=[];foreach($q->fetchAll() as $r)$existing[$r['feature_key']]=$r;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tour Features</title><style>body{font-family:system-ui;background:#f5f7fb;margin:0;color:#172033}.wrap{max-width:1050px;margin:30px auto;padding:0 18px}.box{background:#fff;border-radius:15px;padding:20px;margin:15px 0;box-shadow:0 5px 20px #0001}.feature{border:1px solid #e4e7ec;border-radius:12px;padding:16px;margin:12px 0}.row{display:flex;align-items:center;justify-content:space-between;gap:15px}.switch{display:flex;gap:8px;align-items:center;font-weight:700}.switch input{width:auto}.muted{color:#667085;font-size:13px}input,textarea,button{width:100%;box-sizing:border-box;padding:10px;border:1px solid #d0d5dd;border-radius:8px;font:inherit}textarea{min-height:70px}button{background:#155eef;color:#fff;border:0;font-weight:700;margin-top:12px}.ok{background:#ecfdf3;color:#067647;padding:10px;border-radius:8px}.err{background:#fef3f2;color:#b42318;padding:10px;border-radius:8px}</style></head><body><main class="wrap"><p><a href="saas_dashboard.php">← Dashboard</a></p><h1>Tour Features</h1><p class="muted">Enable only the options this tour needs. Passenger selections remain isolated to this tour.</p><?php if($ok):?><div class="ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="err"><?=saas_h($error)?></div><?php endif;?><div class="box"><?php foreach($catalog as $key=>$c):$r=$existing[$key]??[];$cfg=json_decode((string)($r['config_json']??''),true)?:[];?><form method="post" class="feature"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="feature_key" value="<?=saas_h($key)?>"><div class="row"><div><h2><?=saas_h($c['label'])?></h2><p class="muted"><?=saas_h($c['description'])?></p></div><label class="switch"><input type="checkbox" name="enabled" <?=!empty($r['enabled'])?'checked':''?>> Enabled</label></div><label>Display label</label><input name="label" value="<?=saas_h($cfg['label']??$c['label'])?>"><label>Description</label><textarea name="description"><?=saas_h($cfg['description']??$c['description'])?></textarea><button>Save <?=saas_h($c['label'])?></button></form><?php endforeach;?></div></main></body></html>